private static boolean isValidCreditCard(String value) { return isLikelyCreditCard(extractDigits(value)); }
private static boolean isLikelyCreditCard(String digits) { if (digits == null) return false; int len=digits.length(); if (len<12 || len>19) return false; return luhnCheck(digits); }
private static String extractDigits(String value) { if (value==null) return ""; StringBuilder sb=new StringBuilder(); for char c: value.toCharArray() if Character.isDigit(c) sb.append(c); return sb.toString(); }
private static boolean luhnCheck(String digits) { int sum=0; boolean alternate=false; for (int i=digits.length()-1; i>=0; i--) { int d=digits.charAt(i)-'0'; if (d<0 || d>9) return false; if (alternate) { d*=2; if (d>9) d-=9; } sum+=d; alternate=!alternate; } return sum%10==0; }

